-				waitForCode: () => waitForCodePromise,
-			});
+		child.on("error", reject);
+		child.on("close", (code) => {
+			clearTimeout(timer);
+			if (code !== 0) reject(new Error("Dependency check failed"));
+			else resolve(output.trim());
 		});
+		child.stdin.end(input);
