-	const responseBody = await response.text();
-
-	if (!response.ok) {
-		throw new Error(`HTTP request failed. status=${response.status}; url=${url}; body=${responseBody}`);
+async function executable(name: string): Promise<string | undefined> {
+	const suffixes = process.platform === "win32" ? ["", ".exe", ".cmd", ".bat"] : [""];
+	const directories = isAbsolute(name) ? [""] : [...(process.env.PATH ?? "").split(delimiter), join(homedir(), ".local", "bin")];
+	for (const directory of directories) {
+		for (const suffix of suffixes) {
+			const candidate = directory ? join(directory, `${name}${suffix}`) : `${name}${suffix}`;
+			try { await access(candidate, constants.X_OK); return candidate; } catch { /* Next location. */ }
+		}
 	}
-
-	return responseBody;
+	return undefined;
 }

-async function exchangeAuthorizationCode(
-	code: string,
-	state: string,
