+async function setupProbe(python: string, command: string, type: "status" | "discover" | "version"): Promise<unknown> {
+	const requestId = randomUUID();
+	const line = await run(python, ["-s", "-B", "-u", SETUP_WORKER], JSON.stringify({ v: 1, requestId, type, command, env: claudeCodeEnvironment(undefined, false) }) + "\n", 55_000);
+	const record: unknown = JSON.parse(line);
+	if (!record || typeof record !== "object" || !("v" in record) || record.v !== 1 ||
+		!("requestId" in record) || record.requestId !== requestId || !("type" in record) || record.type !== "result" || !("result" in record)) {
+		throw new Error("Invalid Claude Code setup response");
 	}
+	return record.result;
