+	if (!command) throw new Error("Claude Code executable not found. Restart lunR after installation and retry.");
+	const version = await setupProbe(python, command, "version") as string;
+	if (!version.startsWith(VERSION)) throw new Error(`Claude Code ${VERSION} is the only qualified version. Found ${version.slice(0, 40)}. Subscription requests are disabled until this version is qualified.`);
+	let status = await setupProbe(python, command, "status") as { logged_in?: boolean; plan?: string; accountFingerprint?: string }; 
