import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";
import { calculateCost } from "../models.ts";
import type {
	Api,
	AssistantMessage,
	Context,
	Model,
	SimpleStreamOptions,
	StreamOptions,
	ToolCall,
	Usage,
} from "../types.ts";
import { AssistantMessageEventStream } from "../utils/event-stream.ts";

const WORKER = fileURLToPath(new URL("../../vendor/hermes-claude-subscription-directsdk/lunr_bridge.py", import.meta.url));
const MAX_RECORD = 64 * 1024 * 1024;
const CONFLICTS = [
	"ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_OAUTH_TOKEN", "ANTHROPIC_BASE_URL",
	"ANTHROPIC_FOUNDRY_API_KEY", "CLAUDE_CODE_USE_BEDROCK", "CLAUDE_CODE_USE_VERTEX",
	"CLAUDE_CODE_USE_FOUNDRY", "CLAUDE_CODE_EXTRA_BODY",
] as const;
const ENV_ALLOWLIST = [
	"PATH", "HOME", "USERPROFILE", "APPDATA", "LOCALAPPDATA", "PROGRAMDATA", "SYSTEMROOT",
	"SYSTEMDRIVE", "COMSPEC", "PATHEXT", "TEMP", "TMP", "LANG", "LC_ALL",
	"HTTP_PROXY", "HTTPS_PROXY", "NO_PROXY", "http_proxy", "https_proxy", "no_proxy",
] as const;

export function claudeCodeEnvironment(configDir?: string, strict = true): Record<string, string> {
	const conflicting = CONFLICTS.filter((name) => {
		const value = process.env[name];
		return value && (name !== "CLAUDE_CODE_USE_BEDROCK" && name !== "CLAUDE_CODE_USE_VERTEX" && name !== "CLAUDE_CODE_USE_FOUNDRY"
			|| !["0", "false", "no", "off"].includes(value.toLowerCase()));
	});
	if (strict && conflicting.length) throw new Error(`Claude Code subscription refuses conflicting environment variables: ${conflicting.join(", ")}`);
	if (process.env.NODE_TLS_REJECT_UNAUTHORIZED === "0") throw new Error("Claude Code subscription requires TLS certificate verification");
	const env = Object.fromEntries(ENV_ALLOWLIST.flatMap((name) => process.env[name] ? [[name, process.env[name]]] : []));
	if (configDir) env.CLAUDE_SUBSCRIPTION_DIRECTSDK_CONFIG_DIR = configDir;
	return env;
}

function history(context: Context, model: Model<Api>): { messages: unknown[]; tools: unknown[] } {
	const messages: Record<string, unknown>[] = context.systemPrompt ? [{ role: "system", content: context.systemPrompt }] : [];
	for (const message of context.messages) {
		if (message.role === "user") {
			messages.push({ role: "user", content: typeof message.content === "string" ? message.content : message.content.map((block) =>
				block.type === "text" ? { type: "text", text: block.text } : {
					type: "image_url", image_url: { url: `data:${block.mimeType};base64,${block.data}` },
				}) });
		} else if (message.role === "assistant") {
			const text = message.content.filter((block) => block.type === "text").map((block) => block.text).join("");
			const calls = message.content.filter((block): block is ToolCall => block.type === "toolCall")
				.map((block) => ({ id: block.id, type: "function", function: { name: block.name, arguments: JSON.stringify(block.arguments) } }));
			const projection = { content: text.trim(), tool_calls: calls.map((call) => ({ id: call.id, name: call.function.name, input: JSON.parse(call.function.arguments) })) };
			const carrier = message.provider === "anthropic" && message.model === model.id && message.claudeCodeCarrier?.version === 1
				&& JSON.stringify(message.claudeCodeCarrier.projection) === JSON.stringify(projection)
				? [{ type: "claude-subscription-directsdk-experimental.native_assistant", ...message.claudeCodeCarrier }] : [];
			messages.push({ role: "assistant", content: text, tool_calls: calls, reasoning_details: carrier });
		} else {
			if (message.content.some((block) => block.type !== "text")) throw new Error("Claude Code subscription supports text tool results only");
			messages.push({ role: "tool", tool_call_id: message.toolCallId, content: message.content.map((block) => block.type === "text" ? block.text : "").join(""), is_error: message.isError });
		}
	}
	const tools = (context.tools ?? []).map((tool) => ({ type: "function", function: {
		name: tool.name, description: tool.description, parameters: tool.parameters,
	} }));
	return { messages, tools };
}

function validateOptions(model: Model<Api>, options: StreamOptions | SimpleStreamOptions): void {
	if (!options.externalClaudeCode) throw new Error("Claude Code subscription setup is required. Run /login anthropic.");
	if (options.apiKey || options.headers || options.onPayload || options.onResponse || options.env ||
		options.metadata || options.transport && options.transport !== "auto" || options.maxRetries ||
		options.maxRetryDelayMs || options.websocketConnectTimeoutMs || model.baseUrl !== "https://api.anthropic.com") {
		throw new Error("Claude Code subscription does not support API keys, alternate endpoints, or request mutations");
	}
	const anthro = options as StreamOptions & { toolChoice?: unknown; client?: unknown; extraBody?: unknown; thinkingBudgetTokens?: unknown };
	if (anthro.toolChoice && anthro.toolChoice !== "auto" || anthro.client || anthro.extraBody || anthro.thinkingBudgetTokens) {
		throw new Error("Claude Code subscription does not support forced tools or native request overrides");
	}
	if (options.temperature !== undefined && (options.temperature < 0 || options.temperature > 1)) throw new Error("Unsupported temperature");
}

type WorkerEvent = { v: 1; requestId: string; type: string; text?: unknown; pid?: unknown; response?: unknown };

function parseWorkerRecord(line: string, requestId: string): WorkerEvent {
	if (Buffer.byteLength(line) > MAX_RECORD) throw new Error("Claude Code bridge record exceeds size limit");
	const value: unknown = JSON.parse(line);
	if (!value || typeof value !== "object" || !("v" in value) || value.v !== 1 ||
		!("requestId" in value) || value.requestId !== requestId || !("type" in value) || typeof value.type !== "string") {
		throw new Error("Invalid Claude Code bridge record");
	}
	return value as WorkerEvent;
}

function stopNative(pid: number): void {
	if (!Number.isSafeInteger(pid) || pid < 1) return;
	if (process.platform === "win32") {
		spawn("taskkill", ["/F", "/T", "/PID", String(pid)], { stdio: "ignore", windowsHide: true }).unref();
	} else {
		try { process.kill(-pid, "SIGKILL"); } catch { /* Already exited. */ }
	}
}

function terminate(child: ChildProcessWithoutNullStreams, pid?: number): void {
	if (pid !== undefined) stopNative(pid);
	child.kill();
}

function validatedCompletion(value: unknown, model: Model<Api>, text: string, thinking: string): { content: AssistantMessage["content"]; carrier: AssistantMessage["claudeCodeCarrier"]; usage: Usage; responseId: string; reason: "stop" | "length" | "toolUse" } {
	if (!value || typeof value !== "object" || !("choices" in value) || !Array.isArray(value.choices)) throw new Error("Invalid native completion");
	const response = value as Record<string, unknown> & { choices: { finish_reason: unknown; message: Record<string, unknown> }[]; usage: Record<string, unknown> };
	const choice = response.choices[0];
	if (!choice || !["stop", "length", "tool_calls"].includes(String(choice.finish_reason)) ||
		typeof choice.message?.content !== "string" && choice.message?.content !== null ||
		(choice.message.content ?? "") !== text || (choice.message.reasoning_content ?? "") !== thinking) throw new Error("Native completion differs from streamed content");
	const rawCalls = choice.message.tool_calls ?? [];
	if (!Array.isArray(rawCalls)) throw new Error("Invalid native tool calls");
