export function streamClaudeCode(model: Model<Api>, context: Context, options: StreamOptions | SimpleStreamOptions = {}): AssistantMessageEventStream {
	const stream = new AssistantMessageEventStream();
	const output: AssistantMessage = {
		role: "assistant", api: model.api, provider: model.provider, model: model.id, content: [],
		usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0,
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } },
		stopReason: "stop", timestamp: Date.now(),
	};
	void (async () => {
		let child: ChildProcessWithoutNullStreams | undefined;
		let nativePid: number | undefined;
		let timer: NodeJS.Timeout | undefined;
		let abortTimer: NodeJS.Timeout | undefined;
		let started = false;
		let complete = false;
		let buffer = "";
		let text = "";
		let thinking = "";
		let activeIndex = -1;
		let activeType: "text" | "thinking" | undefined;
		try {
			validateOptions(model, options);
			if (options.signal?.aborted) throw new Error("Claude Code request cancelled");
			const connection = options.externalClaudeCode!;
