				model: model.id, ...input, extraBody: {
				...(options.maxTokens ? { max_tokens: options.maxTokens } : {}),
				...("reasoning" in options && options.reasoning ? { reasoning: { enabled: true, effort: options.reasoning } } : {}),
			}, timeout: Math.min(300, Math.max(1, Math.round((options.timeoutMs ?? 180_000) / 1000))) };
