									if (!started || complete || typeof event.text !== "string") throw new Error("Invalid Claude Code stream delta");
									resetDeadline();
									const kind = event.type === "text_delta" ? "text" : "thinking";
									if (activeType !== kind) {
										if (activeType === "text") stream.push({ type: "text_end", contentIndex: activeIndex, content: (output.content[activeIndex] as { text: string }).text, partial: output });
										if (activeType === "thinking") stream.push({ type: "thinking_end", contentIndex: activeIndex, content: (output.content[activeIndex] as { thinking: string }).thinking, partial: output });
										activeIndex = output.content.length;
										activeType = kind;
										if (kind === "text") { output.content.push({ type: "text", text: "" }); stream.push({ type: "text_start", contentIndex: activeIndex, partial: output }); }
										else { output.content.push({ type: "thinking", thinking: "" }); stream.push({ type: "thinking_start", contentIndex: activeIndex, partial: output }); }
									}
									const block = output.content[activeIndex];
									if (kind === "text" && block?.type === "text") { text += event.text; block.text += event.text; stream.push({ type: "text_delta", contentIndex: activeIndex, delta: event.text, partial: output }); }
									if (kind === "thinking" && block?.type === "thinking") { thinking += event.text; block.thinking += event.text; stream.push({ type: "thinking_delta", contentIndex: activeIndex, delta: event.text, partial: output }); }
								} else if (event.type === "complete") {
									if (!started || complete) throw new Error("Invalid Claude Code completion order");
									const result = validatedCompletion(event.response, model, text, thinking);
									complete = true;
									if (activeType === "text") stream.push({ type: "text_end", contentIndex: activeIndex, content: (output.content[activeIndex] as { text: string }).text, partial: output });
									if (activeType === "thinking") stream.push({ type: "thinking_end", contentIndex: activeIndex, content: (output.content[activeIndex] as { thinking: string }).thinking, partial: output });
