	const carrier = Array.isArray(details) ? details.find((entry) => entry?.type === "claude-subscription-directsdk-experimental.native_assistant") : undefined;
	const projection = { content: text.trim(), tool_calls: calls.map((call) => ({ id: call.id, name: call.name, input: call.arguments })) };
	if (!carrier || carrier.version !== 1 || !Array.isArray(carrier.messages) ||
