									if (activeType === "thinking") stream.push({ type: "thinking_end", contentIndex: activeIndex, content: (output.content[activeIndex] as { thinking: string }).thinking, partial: output });
									output.content = [...output.content.filter((block) => block.type !== "toolCall"), ...result.content.filter((block) => block.type === "toolCall")];
									output.claudeCodeCarrier = result.carrier;
									output.responseId = result.responseId;
									output.usage = result.usage;
									output.stopReason = result.reason;
									for (let index = 0; index < output.content.length; index++) {
										const block = output.content[index];
										if (block.type === "toolCall") { stream.push({ type: "toolcall_start", contentIndex: index, partial: output }); stream.push({ type: "toolcall_end", contentIndex: index, toolCall: block, partial: output }); }
									}
								} else if (event.type === "error" || event.type === "cancelled") throw new Error("Claude Code request failed. Check subscription setup and native CLI compatibility.");
							else throw new Error("Unknown Claude Code bridge event");
							}
						} catch (error) { reject(error); }
					});
					worker.on("close", () => complete ? resolve() : reject(new Error("Claude Code bridge exited without a validated completion")));
				});
			} finally {
				options.signal?.removeEventListener("abort", abort);
			}
			if (options.signal?.aborted) throw new Error("Claude Code request cancelled");
			stream.push({ type: "done", reason: output.stopReason as "stop" | "length" | "toolUse", message: output });
		} catch {
			output.content = [];
			output.claudeCodeCarrier = undefined;
			output.stopReason = options.signal?.aborted ? "aborted" : "error";
			output.errorMessage = options.signal?.aborted ? "Claude Code request cancelled" : "Claude Code request failed. Check subscription setup and native CLI compatibility.";
			stream.push({ type: "error", reason: output.stopReason, error: output });
		} finally {
			if (timer) clearTimeout(timer);
			if (abortTimer) clearTimeout(abortTimer);
			if (child && child.exitCode === null) terminate(child, nativePid);
		}
	})();
	return stream;
}

