rmSync(outdir, { recursive: true, force: true });
const result = await build({
	absWorkingDir: root,
	entryPoints: ["cli-runtime", "main", "index", "rpc-entry"].map((name) => join(dist, `${name}.js`)),
	outdir,
	bundle: true,
	splitting: true,
	format: "esm",
	platform: "node",
	target: "node22",
